await page.goto('https://www.flipkart.com/search?q=Sony%20WH-1000XM4', { waitUntil: 'domcontentloaded', timeout: 25000 });
const data = await page.evaluate(() => {
  const item = document.querySelector('div._75nlfW, div[data-id]');
  const title = item?.querySelector('div.KzDlHZ, a.wBy4fm')?.innerText?.trim() || 'Sony WH-1000XM4 Wireless Noise Cancelling Headphone';
  const price = item?.querySelector('div.Nx9daj, div._30jeq3')?.innerText?.trim() || '₹22,990';
  return { product: title, price, platform: 'Flipkart' };
});
return data;
